sys_script_email.script:
(function runMailScript(/* GlideRecord */ current, /* TemplatePrinter */ template,
          /* Optional EmailOutbound */ email, /* Optional GlideRecord */ email_action,
          /* Optional GlideRecord */ event) {

          // Add your code here
    // Tenta obter o sys_id da base a partir de 'current' ou 'template'
    var baseSysId = current.sys_id || template.sys_id;

    if (!baseSysId) {
        template.print('<li>Erro: Não foi possível identificar a base.</li>');
        return;
    }

    // Cria um GlideRecord para buscar os registros aprovados
    var grRegistrados = new GlideRecord('x_1590789_bases_user_registration');
    grRegistrados.addQuery('base', baseSysId);
    grRegistrados.addQuery('state', '=', '3');
    grRegistrados.query();

    var listaUsuarios = '';

    // Itera sobre os registros e constrói a lista em HTML
    while (grRegistrados.next()) {
        var nomeUsuario = grRegistrados.opened_by.getDisplayValue();
        var emailUsuario = grRegistrados.opened_by.email;
        listaUsuarios += '<li>' + nomeUsuario + ' - ' + emailUsuario + '</li>';
    }

    // Verifica se a lista está vazia
    if (listaUsuarios) {
        template.print(listaUsuarios);
    } else {
        template.print('<li>Nenhum usuário registrado encontrado.</li>');
    }


})(current, template, email, email_action, event);
